// Megaball Neo — developed by Loxy. A modern tribute to Ed & Al Mackey's Amiga classic.
// Game logic + bricks/ball/particles are Canvas2D; backdrop, title, paddle, capsules and banners
// are live Rive state machines (generated by rive-mcp, see tools/build-rive.mjs). Two views share the
// same game: HUD (mission-control UI around a WebGL Earth) and ARCADE (the original synthwave look).
import { createMusic } from "./music.js";
import { createPlanet } from "./planet.js";
import { LEVELS, levelFor } from "./levels.js";
import { createBoard } from "./leaderboard.js";
import RiveFactory from "./vendor/rive/canvas_advanced.mjs"; // @rive-app/canvas-advanced 2.43.1, vendored for offline/desktop

